class Solution:
    def maxFrequencyScore(self, nums: List[int], k: int) -> int:
        if not nums:
            return 0
        if len(nums) == 1:
            return 1

        nums.sort()
        sum_vals = [0] + list(accumulate(nums))
        left = 0
        max_freq = 1

        for right in range(1, len(sum_vals)):
            while left < right:
                mid = (right + left) // 2
                val = (sum_vals[right] - sum_vals[mid]) - (right - mid) * nums[mid]
                if val > k:
                    left += 1
                else:
                    break

            max_freq = max(max_freq, right - left)

        return max_freq

