class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        maxit = SortedDict()
        n = len(nums)

        for i in range(n):
            if nums[i] in maxit:
                continue

            prev_idx = maxit.bisect_left(nums[i]) - 1

            if prev_idx >= 0:
                maxit[nums[i]] = max(maxit.get(nums[i], 0), maxit.peekitem(prev_idx)[1] + nums[i])
            else:
                maxit[nums[i]] = nums[i]

            next_idx = maxit.bisect_right(nums[i])

            if next_idx < len(maxit.keys()) and maxit.peekitem(next_idx)[0] <= maxit[nums[i]]:
                del maxit[maxit.peekitem(next_idx)[0]]

        return max(maxit.values(), default=0)

