class Solution:
    def maximumPoints(self, edges: List[List[int]], coins: List[int], k: int) -> int:
        adj_list = defaultdict(list)

        for a, b in edges:
            adj_list[a].append(b)
            adj_list[b].append(a)

        @lru_cache(None)
        def dp(i: int, floors: int) -> int:
            c = coins[i] >> floors
            no_floor = c - k if c > k else 0
            floor = 0

            for e in adj_list[i]:
                no_floor += dp(e, floors)
                floor += dp(e, floors + 1)

            return max(no_floor, floor)

        return dp(0, 0)

class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        mod = 10**9 + 7
        ss = s + s
        if t not in ss:
            return 0

        n = len(s)
        r = n // ss.find(t) if s != t else 0

        f0 = 0 if s != t else 1
        f1 = r - f0

        left = f0 if k % 2 == 0 else f1

        if k % 2 == 0:
            a1 = (n - 2) * r
        else:
            a1 = (n - 2) * (n - 1) * r

        q = (n - 1) ** 2

        if q == 1:
            ans = (a1 * (pow(q, k // 2, mod) - 1) // (q - 1) + left) % mod
        else:
            ans = (a1 * (k // 2) + left) % mod

        return ans % mod

