class Solution:
    def countKSubsequencesWithMaxBeauty(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        counter = Counter(s)

        if len(counter) < k:
            return 0

        freq = Counter(counter.values())
        pairs = sorted(freq.items(), reverse=True)

        res = 1
        unique_counts = 0

        for fc, occ in pairs:
            if unique_counts < k:
                if unique_counts + occ <= k:
                    res = (res * pow(fc, occ, mod)) % mod
                    unique_counts += occ
                else:
                    res = (res * comb(occ, k - unique_counts) * pow(fc, k - unique_counts, mod)) % mod
                    break

        return res % mod

