class Solution:
    def minimumTime(self, nums1: List[int], nums2: List[int], x: int) -> int:
        n = len(nums1)
        s = sum(nums1)
        d = sum(nums2)

        if s <= x:
            return 0  # initial sum is already <= x

        ind = sorted(range(n), key=lambda i: nums2[i])
        dp = [0] * (n + 1)
        r = n + 1

        for i in range(1, n + 1):
            for j in range(min(i, r - 1), 0, -1):
                dp[j] = max(dp[j], dp[j - 1] + nums2[ind[i - 1]] * nums1[ind[i - 1]])
                if s + d - dp[j] <= x:
                    r = min(r, j)

        return r if r <= n else -1  # return minimum time or -1 if not possible

